def parse_measure(title, text):
    m = re.match(r'^(Measure [\w-]+)[\s]*[:\-][\s]*(.+?)\*?$', title)
    if m:
        name, jurisdiction = m.group(1), m.group(2).rstrip('*').strip()
    else:
        name, jurisdiction = title, ''
    # description: drop the trailing "Full Text | ..." links line and leading vote-threshold line stays (it's part of registrar text)
    desc = re.sub(r'\n\n(Full Text|Argument|Impartial|Tax Rate).*$', '', text, flags=re.DOTALL).strip()
    desc = re.sub(r'\*\*All related documents are filed and on public review with the city clerk\.?$', '', desc).strip()
    return name, jurisdiction, desc

