    flag = ''
    if 'Paso Robles' in jurisdiction:
        flag = ('Cross-county jurisdiction: Paso Robles Joint Unified School District is based in San Luis '
                'Obispo County - the source page marks this with an asterisk (footnote symbol, no footnote '
                'text found on page) - verify before publishing under "Monterey County"')
